  const N = window.__NEXUS__;
  N.start();
  const log = [];
  const forms = ['pulse','mortar','cryo','blaze','tesla','rail'];
  for (let w = 1; w <= 20; w++) {
    const u0 = N.getUI();
    if (u0.mode !== 'prep') { log.push({w, badMode:u0.mode}); break; }
    // Buy upgrades while affordable, prefer upgrades
    let guard = 0;
    while (guard++ < 12) {
      const u = N.getUI();
      if (!u.upgradeCost || u.gold < u.upgradeCost) break;
      const r = N.upgrade();
      if (!r.ok) break;
    }
    // choose a form alternating if affordable; avoid same
    const ui = N.getUI();
    const pick = forms[(w - 1) % forms.length];
    if (ui.form !== pick) {
      const r = N.reforge(pick);
      if (!r.ok && ui.gold >= 45) {
        // fall back to cheapest available alternate
        for (const f of ['pulse','mortar','cryo','blaze','tesla','rail']) {
          if (f !== ui.form && N.reforge(f).ok) break;
        }
      }
    }
    const started = N.startWave();
    if (!started) { log.push({w, startFail:true, mode:N.getUI().mode}); break; }
    let secs = 0;
    while (secs < 120) {
      N.advance(1);
      secs += 1;
      const u = N.getUI();
      if (u.mode !== 'wave') break;
    }
    const u = N.getUI();
    log.push({w, mode:u.mode, lives:u.lives, gold:u.gold, score:u.score, level:u.level, kills:u.kills, secs});
    if (u.mode === 'victory' || u.mode === 'gameover') break;
  }
  const u = N.getUI();
  return {final:{mode:u.mode,wave:u.wave,lives:u.lives,gold:u.gold,score:u.score,level:u.level,kills:u.kills}, log};
